CREATE TABLE trades(transaction_id INTEGER PRIMARY KEY REFERENCES transactions(transaction_id), product_id TEXT NOT NULL, listing_id TEXT, side TEXT NOT NULL CHECK(side IN ('BUY','SELL')), quantity TEXT NOT NULL CHECK(typeof(quantity)='text'), price TEXT NOT NULL CHECK(typeof(price)='text'), trade_date TEXT NOT NULL, trade_time TEXT, scheduled_settlement_date TEXT);
CREATE TABLE trade_fees(trade_transaction_id INTEGER NOT NULL REFERENCES trades(transaction_id), fee_type TEXT NOT NULL CHECK(fee_type IN ('COMMISSION','EXCHANGE_FEE','REGULATORY_FEE','OTHER')), amount TEXT NOT NULL CHECK(typeof(amount)='text'), PRIMARY KEY(trade_transaction_id,fee_type));
CREATE TABLE position_entries(position_entry_id INTEGER PRIMARY KEY AUTOINCREMENT, source_transaction_id INTEGER NOT NULL UNIQUE REFERENCES transactions(transaction_id));
CREATE TABLE position_lines(position_line_id INTEGER PRIMARY KEY AUTOINCREMENT, position_entry_id INTEGER NOT NULL REFERENCES position_entries(position_entry_id), position_id INTEGER NOT NULL REFERENCES positions(position_id), line_type TEXT NOT NULL CHECK(line_type IN ('OWNERSHIP','LOCATION')), quantity_delta TEXT NOT NULL CHECK(typeof(quantity_delta)='text'), owner_id INTEGER REFERENCES owners(owner_id), financial_account_id INTEGER REFERENCES financial_accounts(financial_account_id), CHECK((line_type='OWNERSHIP' AND owner_id IS NOT NULL AND financial_account_id IS NULL) OR (line_type='LOCATION' AND financial_account_id IS NOT NULL AND owner_id IS NULL)));
CREATE TABLE position_cost_basis_lots(cost_basis_lot_id INTEGER PRIMARY KEY AUTOINCREMENT, source_transaction_id INTEGER NOT NULL UNIQUE REFERENCES transactions(transaction_id), position_id INTEGER NOT NULL REFERENCES positions(position_id), owner_id INTEGER NOT NULL REFERENCES owners(owner_id), financial_account_id INTEGER NOT NULL REFERENCES financial_accounts(financial_account_id), quantity_acquired TEXT NOT NULL CHECK(typeof(quantity_acquired)='text'), book_cost_basis TEXT NOT NULL CHECK(typeof(book_cost_basis)='text'));
CREATE TABLE position_cost_basis_allocations(investment_journal_line_id INTEGER NOT NULL REFERENCES journal_lines(journal_line_id), source_cost_basis_lot_id INTEGER NOT NULL REFERENCES position_cost_basis_lots(cost_basis_lot_id), quantity_disposed TEXT NOT NULL CHECK(typeof(quantity_disposed)='text'), book_cost_disposed TEXT NOT NULL CHECK(typeof(book_cost_disposed)='text'), PRIMARY KEY(investment_journal_line_id,source_cost_basis_lot_id));
CREATE INDEX ix_position_bucket ON position_lines(position_id,financial_account_id);
CREATE INDEX ix_lot_bucket ON position_cost_basis_lots(position_id,owner_id,financial_account_id);
